---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Toast: One notification that changes shape with its state.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change toast.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './toast.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="toast" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="tst dm">
  <div class="dm-main"><div class="tst-slot" aria-live="polite"></div></div>
  <div class="demo"><div class="seg2" role="group" aria-label="State"><button aria-pressed="true" data-v="ok">Success</button><button aria-pressed="false" data-v="err">Error</button><button aria-pressed="false" data-v="info">Info</button><button aria-pressed="false" data-v="load">Loading</button></div></div>
</div>
  </Fragment></div>
</div>
<script>
  import './toast.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Toast ---------- */
/* the toast on its way out and the one coming in share one cell, so each keeps its full width while they cross; a toast
   shorter than the cell sits centred in it, so it is centred in its stage (owner, 18 Nov) */
.tst-slot{min-height:64px;width:100%;display:grid;justify-items:center;align-items:center}
.tst-slot>*{grid-area:1/1}
/* the same size as a toast in Toast stack: width, padding, type and icons */
.tst-t{display:flex;align-items:center;gap:var(--dm-s-3);padding:var(--dm-s-3);background:var(--dm-raised);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow-toast);max-width:380px;width:100%;position:relative;overflow:hidden}
.tst-t .g{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;flex:none}
.tst-t .tx{flex:1;min-width:0;font-size:13px;line-height:1.35}
.tst-t .tx b{font-weight:500;display:block}
.tst-t .tx span{font-size:12px;color:var(--dm-muted)}
.tst-t .acts{display:flex;align-items:center;gap:2px}
.tst-t .life{display:none}
.tst-in{animation:tstin .6s var(--dm-ease) both}
@keyframes tstin{from{opacity:0;transform:translateY(14px) scale(.97);filter:blur(5px)}to{opacity:1;transform:none;filter:none}}
.tst-out{animation:tstout .35s var(--dm-ease) both}
@keyframes tstout{to{opacity:0;transform:translateY(8px) scale(.98);filter:blur(4px)}}
/* Clean (lead, 18 Nov): a toast is a small card, not a pill: its content 16px in from every edge and ordinary round corners
   (16px), with the hairline and the raised shadow. The status shows only on its small icon, with no disc behind it: green for
   success, red for an error; info and loading stay grey, so a toast carries two hues at most. It rises 8px from .98 and
   leaves with a fade, with no blur */
:root[data-style="clean"] .tst-t,:root [data-style="clean"] .tst-t,:root [data-style="clean"].tst-t{gap:12px;padding:16px;border-radius:calc(12px * var(--dm-rk-l,var(--dm-rk)))}
:root[data-style="clean"] .tst-t .g,:root [data-style="clean"] .tst-t .g,:root [data-style="clean"].tst-t .g{width:20px;height:20px;background:none!important;color:var(--dm-fg2)!important}
:root[data-style="clean"] .tst-t .g .i,:root [data-style="clean"] .tst-t .g .i,:root [data-style="clean"].tst-t .g .i{width:20px;height:20px}
:root[data-style="clean"] .tst-t .g .spin,:root [data-style="clean"] .tst-t .g .spin,:root [data-style="clean"].tst-t .g .spin{width:14px;height:14px}
:root[data-style="clean"] .tst-t .g[data-tone="success"],:root [data-style="clean"] .tst-t .g[data-tone="success"],:root [data-style="clean"].tst-t .g[data-tone="success"]{color:var(--dm-ok-mark)!important}
:root[data-style="clean"] .tst-t .g[data-tone="error"],:root [data-style="clean"] .tst-t .g[data-tone="error"],:root [data-style="clean"].tst-t .g[data-tone="error"]{color:var(--dm-bad-mark)!important}
:root[data-style="clean"] .tst-t .acts,:root [data-style="clean"] .tst-t .acts,:root [data-style="clean"].tst-t .acts{gap:4px}
/* the buttons in its row are one height: the close button is as tall as the 28px pill beside it */
:root[data-style="clean"] .tst-t .ib,:root [data-style="clean"] .tst-t .ib,:root [data-style="clean"].tst-t .ib{width:28px;height:28px}
@keyframes tstoutc{to{opacity:0;transform:translateY(6px) scale(.98)}}
:root[data-style="clean"] .tst-in,:root [data-style="clean"] .tst-in,:root [data-style="clean"].tst-in{animation:clcard var(--dm-t-slow) var(--dm-ease) both}
:root[data-style="clean"] .tst-out,:root [data-style="clean"] .tst-out,:root [data-style="clean"].tst-out{animation:tstoutc var(--dm-t-fast) var(--dm-ease) both}
/* with no blur to hide them, the two never show through each other: a new toast rises once the old one has faded */
:root[data-style="clean"] .tst-out~.tst-in,:root [data-style="clean"] .tst-out~.tst-in,:root [data-style="clean"].tst-out~.tst-in{animation-delay:.16s}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, html, seg, swap } from '../core/core.js';
DM.def('toast', (r, c) => {
  const slot = $('.tst-slot', r);
  // each state's icon, colours and words; its tone (data-tone) is what Clean colours: success green, error red, the rest grey
  const V = {
    ok:{ g:'ok', tone:'success', col:'var(--dm-ok)', bg:'var(--dm-ok-bg)', b:'Changes applied', s:'4 files updated in PricingCard', act:'<button class="pill ghost sm tst-undo">Undo</button>' },
    err:{ g:'alert', tone:'error', col:'var(--dm-bad)', bg:'var(--dm-bad-bg)', b:'Could not push to main', s:'The branch is protected', act:'<button class="pill primary sm tst-retry">Retry</button>' },
    info:{ g:'info', tone:'info', col:'var(--dm-pb)', bg:'var(--dm-pb-bg)', b:'Preview is ready', s:'pricing-spacing.preview.app', act:'<button class="pill ghost sm">Open</button>' },
    load:{ g:'load', tone:'loading', col:'var(--dm-fg)', bg:'var(--dm-chip)', b:'Deploying preview', s:'Building 3 pages', act:'' }
  };
  let cur = null;
  let show = function(k){
    const v = V[k];
    const t = html(`<div class="tst-t tst-in" role="status"><span class="g" data-tone="${v.tone}" style="color:${v.col};background:${v.bg}">${k === 'load' ? '<span class="spin"></span>' : I(v.g)}</span><div class="tx"><b>${v.b}</b><span>${v.s}</span></div><div class="acts">${v.act}<button class="ib" aria-label="Dismiss" data-tip="Dismiss">${I('x')}</button></div><span class="life"></span></div>`);
    if (cur){ const old = cur; old.classList.add('tst-out'); setTimeout(() => old.remove(), 300); }
    slot.appendChild(t); cur = t;
    $('.ib', t).onclick = () => { t.classList.add('tst-out'); setTimeout(() => t.remove(), 300); cur = null; };
    const u = $('.tst-undo', t); if (u) u.onclick = () => { $('.tx b', t).textContent = 'Changes undone'; swap($('.tx span', t), 'PricingCard is back as it was'); u.remove(); };
    const rt = $('.tst-retry', t); if (rt) rt.onclick = () => { rt.innerHTML = '<span class="spin"></span>'; setTimeout(() => { if (t.isConnected) show('ok'); }, 1200); };
    if (k === 'load') c.later(2600, () => { if (cur === t) show('info'); });
    if (k === 'ok' || k === 'info'){
      // it times out like a real toast: hovering holds it, and when it runs out it leaves and the same one comes back (until
      // you take over: then it stays gone until you pick one)
      const life = $('.life', t).animate([{ transform:'scaleX(1)' }, { transform:'scaleX(0)' }], { duration:5200, fill:'forwards' });
      t.addEventListener('pointerenter', () => life.pause()); t.addEventListener('pointerleave', () => life.play());
      life.finished.then(() => { if (cur !== t || c.dead) return; t.classList.add('tst-out'); cur = null; setTimeout(() => t.remove(), 300); c.auto(1100, () => { if (!cur) show(k); }); }).catch(() => {});
    }
  }
  const sg = $('.seg2', r), knob = seg(sg, v => show(v));
  const sync = k => { $$('button', sg).forEach(b => b.setAttribute('aria-pressed', b.dataset.v === k)); knob.place(); };
  const show0 = show; show = k => { sync(k); show0(k); };
  // a state picked before this first one lands stays
  c.later(400, () => { if (!cur) show('ok'); });
});
